import './CommentGen.css';
import React, { useRef, useState } from 'react';


function CommentGen(User, {setCommentsList, commentsList}) {

    console.log('render');
    const [search, setSearch] = useState('');
    const addComments = (text) => {
        const userName = User._firstName + User.lastName;
        const comment = {
            "id":0,
            "userPic": User._picter,
            "name": userName,
            text
        }
        console.log(commentsList);
        setCommentsList([comment, ...commentsList])
    }
    const searchBox = useRef(null)
   
    return (
        <div className='Comments'>
            <div className='writeComment'>
                <img src="/images/tailand.jpeg" alt="" />
                <input ref={searchBox} class="search" value={search} onChange={e => setSearch(e.currentTarget.value)} placeholder="write a comment?"
                    aria-label="Search"></input>
                <div className='set'>
                    <button className='set-button' onClick={() => addComments(search)}>set</button>
                </div>
            </div>
        </div>
    );
}

export default CommentGen;
